package com.example.spring_demo1_ai.controller; import com.example.spring_demo1_ai.model.User; import com.example.spring_demo1_ai.service.UserService; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.web.bind.annotation.GetMapping; import org.springframework.web.bind.annotation.RestController; import java.util.List; @RestController public class UserController { private final UserService userService; @Autowired public UserController(UserService userService) { this.userService = userService; } @GetMapping("/active-users") public List<User> getAllActiveUsers() { return userService.getAllActiveUsers(); } }